// Package broadcaststation owns the directory of over-the-air TV stations a filler clip can name
// (#2059): each station's community of license and the dated call signs it has held. It is shipped
// data, generated by cmd/station-data and seeded into the database at boot; runtime reads the
// database, never the embedded file.
//
// A Broadcast station is not a Loomarr Channel. Station material (news updates, weather, station IDs)
// recorded off one of these stations is local to it.
package broadcaststation

import (
	"fmt"
	"math"
	"regexp"
	"strings"
	"time"
)

// Station is one broadcast TV station: a stable identity, where it is licensed, and every call sign
// it held. ID is "fcc:<facility id>" for stations the FCC records, or "wd:<Wikidata QID>" for the
// few known only from Wikidata.
type Station struct {
	ID        string
	Country   string // ISO 3166-1 alpha-2; US territories carry their own code (PR, GU, ...)
	City      string
	Region    string // state or territory postal code
	Latitude  float64
	Longitude float64
	CallSigns []CallSign
}

// CallSign is one base call sign and the dates it was valid. From and To are YYYY-MM-DD; an empty
// bound is open (the record does not say when it started or that it ended). To is exclusive.
type CallSign struct {
	Sign string
	From string
	To   string
}

// The base call sign an archive title uses: four or three letters, US K/W prefixes. Suffixes such as
// -TV and -DT are licensing detail a title routinely drops ("WEWS NewsChannel 5", "CBS/WJW 8").
var baseCallSign = regexp.MustCompile(`^[KW][A-Z]{2,3}$`)

var callSignSuffixes = []string{"-TV", "-DT", "-CD", "-CA", "-LD", "-LP", "-HD"}

// NormalizeCallSign returns the base call sign, or "" when s is not a US TV call sign.
func NormalizeCallSign(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	for _, suffix := range callSignSuffixes {
		if trimmed, ok := strings.CutSuffix(s, suffix); ok {
			s = trimmed
			break
		}
	}
	if !baseCallSign.MatchString(s) {
		return ""
	}
	return s
}

// CallSignOn returns the call sign the station held on date (YYYY-MM-DD), or its latest when the
// date is empty or outside every span.
func (s Station) CallSignOn(date string) string {
	if len(s.CallSigns) == 0 {
		return ""
	}
	if date != "" {
		for _, c := range s.CallSigns {
			if (c.From == "" || c.From <= date) && (c.To == "" || date < c.To) {
				return c.Sign
			}
		}
	}
	return s.CallSigns[len(s.CallSigns)-1].Sign
}

// CallSignsDuring returns every call sign the station held on some day in [from, to), oldest first.
// Bounds are YYYY-MM-DD and an empty bound is open, so ("", "") is every call sign it ever held.
func (s Station) CallSignsDuring(from, to string) []string {
	span := CallSign{From: from, To: to}
	var out []string
	for _, c := range s.CallSigns {
		if overlaps(c, span) {
			out = append(out, c.Sign)
		}
	}
	return out
}

// Validate reports a station the directory could not resolve against.
func (s Station) Validate() error {
	if !strings.HasPrefix(s.ID, "fcc:") && !strings.HasPrefix(s.ID, "wd:") {
		return fmt.Errorf("station %q: id must be fcc:<facility> or wd:<item>", s.ID)
	}
	if len(s.Country) != 2 || strings.ToUpper(s.Country) != s.Country {
		return fmt.Errorf("station %s: country %q must be ISO alpha-2", s.ID, s.Country)
	}
	if math.IsNaN(s.Latitude) || s.Latitude < -90 || s.Latitude > 90 ||
		math.IsNaN(s.Longitude) || s.Longitude < -180 || s.Longitude > 180 {
		return fmt.Errorf("station %s: coordinates out of range", s.ID)
	}
	if len(s.CallSigns) == 0 {
		return fmt.Errorf("station %s: no call signs", s.ID)
	}
	for i, c := range s.CallSigns {
		// A station holds one call sign at a time: spans are in order and never overlap. Only the
		// first may have an open start and only the last an open end.
		if i > 0 {
			prev := s.CallSigns[i-1]
			if c.From == "" || prev.To == "" || prev.To > c.From {
				return fmt.Errorf("station %s: call sign %s overlaps %s", s.ID, c.Sign, prev.Sign)
			}
		}
		if NormalizeCallSign(c.Sign) != c.Sign {
			return fmt.Errorf("station %s: call sign %q is not a base call sign", s.ID, c.Sign)
		}
		for _, bound := range []string{c.From, c.To} {
			if bound == "" {
				continue
			}
			if _, err := time.Parse(time.DateOnly, bound); err != nil {
				return fmt.Errorf("station %s: call sign %s date %q must be YYYY-MM-DD", s.ID, c.Sign, bound)
			}
		}
		if c.From != "" && c.To != "" && c.From >= c.To {
			return fmt.Errorf("station %s: call sign %s ends before it starts", s.ID, c.Sign)
		}
	}
	return nil
}
